 async function downloadDesign(){if(!entry||!studioSource||dirty||isBusy())return;working('design-download');setError('');const controller=new AbortController();abort.current=controller;try{const frozen=await request<{entry:PublicationRecord;project:SocialProject|null}>('planner/'+entry.id);if(!frozen.project||frozen.entry.revision!==entry.revision)throw new Error('Die Planung wurde inzwischen geändert. Bitte den aktuellen Stand neu laden.');const render=await import('@/lib/social/export');await render.exportBundle([{...frozen.project,caption:entry.caption}],{signal:controller.signal,imageFormat:'png',includeVideo:entry.kind==='reel',filename:render.safeFilename(entry.source.title),onProgress:value=>setProgress(value.label)});if(!controller.signal.aborted)setNotice('Design mit Ihrer aktuellen Planungs-Caption heruntergeladen. Der Export wird nicht an eine Plattform gesendet.');}catch(reason){if(!controller.signal.aborted)message(reason);}finally{abort.current=null;working('');setProgress('');}}
 async function copyCaption(){if(!draft)return;try{await navigator.clipboard.writeText(draft.caption);setNotice('Caption kopiert.');}catch{setError('Die Zwischenablage ist nicht verfügbar. Markieren und kopieren Sie den Text im Caption-Feld.');}}
 async function reload(){if(isBusy())return;if(dirty||secondaryDirty){setError('Bitte zuerst speichern oder die offenen Änderungen bewusst schließen. Ihr lokaler Stand bleibt erhalten.');return;}working('reload');setError('');try{setWorkspace(await request<PlannerWorkspace>('planner'));if(entry){const loaded=await request<{entry:PublicationRecord;project:SocialProject|null}>('planner/'+entry.id);store(loaded.entry);setProject(loaded.project);}}catch(reason){message(reason);}finally{working('');}}
 function openConnection(value:ConnectionView|null){if(isBusy())return;{setConnectionEdit(value);setConnectionForm({id:value?.id??uid(),label:value?.label??'Mein Instagram',accountId:value?.accountId??'',accessToken:'',expiresAt:value?.expiresAt?localWallTime(value.expiresAt,'UTC'):'',confirmed:false});setError('');}}
 function closeConnection(){if(locked)return;if(connectionDirty&&!window.confirm('Den noch nicht gespeicherten Zugang verwerfen?'))return;setConnectionEdit(undefined);setConnectionForm(value=>({...value,accessToken:''}));}
 function connectionChanged(value:ConnectionView){setWorkspace(previous=>({...previous,connections:previous.connections.some(item=>item.id===value.id)?previous.connections.map(item=>item.id===value.id?value:item):[...previous.connections,value]}));}
 async function refreshConnections(){try{const latest=await request<PlannerWorkspace>('planner');setWorkspace(latest);const current=entry&&latest.entries.find(value=>value.id===entry.id);if(current&&current.revision!==entry?.revision){if(dirty)setConflict(true);else store(current);}}catch{setError('Der Zugang wurde gespeichert. Die Übersicht konnte gerade nicht aktualisiert werden. Bitte den aktuellen Stand erneut laden.');}}
 async function saveConnection(){if(isBusy()||!connectionForm.confirmed)return;const expiry=resolveWallTime(connectionForm.expiresAt,'UTC');if(expiry.length!==1){setError('Bitte das tatsächliche Ablaufdatum und die Uhrzeit in UTC auswählen.');return;}working('connection-save');setError('');try{const value=await request<ConnectionView>('connections/save',{id:connectionForm.id,idempotencyKey:uid(),baseRevision:connectionEdit?.revision??0,brandKey:'default',label:connectionForm.label,accountId:connectionForm.accountId,accessToken:connectionForm.accessToken,expiresAt:expiry[0].instant,permissionsConfirmed:true});connectionChanged(value);await refreshConnections();setConnectionEdit(undefined);setConnectionForm(previous=>({...previous,accessToken:''}));setNotice('Zugang verschlüsselt gespeichert. Prüfen Sie jetzt die Kontoverbindung. Betroffene Beiträge brauchen danach eine neue Freigabe.');}catch(reason){message(reason);}finally{working('');}}
 async function connectionAction(action:'check'|'disconnect',value:ConnectionView){if(isBusy())return;if(action==='disconnect'&&!window.confirm('Diese Verbindung trennen und bisherige Veröffentlichungsfreigaben stoppen?'))return;working('connection-'+action);setError('');try{const checked=await request<ConnectionView>('connections/'+action,{id:value.id,baseRevision:value.revision,idempotencyKey:uid()});connectionChanged(checked);await refreshConnections();if(checked.lastError)setError(checked.lastError);setNotice(action==='disconnect'?'Die Verbindung wurde getrennt.':'Der Kontostatus wurde geprüft.');}catch(reason){message(reason);}finally{working('');}}
 const canApprove=Boolean(entry&&draft&&!manual&&effectiveDelivery(draft)===(selectedSpec?.delivery??'automatic')&&executable&&optionsReady&&(draft.kind==='text'||(draft.carousel?carouselItemsReady(entry):entry.media))&&entry.accountId&&entry.scheduledAt&&!entry.process.publishStartedAt&&['draft','prepared','failed','cancelled'].includes(entry.status)&&selectedConnection?.status==='connected'&&workspace.readiness.enabled&&workspace.readiness.queue&&workspace.readiness.media&&workspace.readiness.publicOrigin&&workspace.readiness.credentials!==false&&!dirty&&!locked);
 const title=new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric'}).format(month);
 function entryButton(item:PublicationRecord){return <button key={item.id} type="button" className={`planner-entry planner-entry--${item.status}`} onClick={()=>openExisting(item.id)}><span className="planner-entry-time">{item.scheduledAt?new Intl.DateTimeFormat('de-DE',{timeZone:calendarZone,hour:'2-digit',minute:'2-digit'}).format(new Date(item.scheduledAt)):t("Ohne Datum")} · {platformGuide(effectivePlatform(item)).label}</span><strong>{item.source.title}</strong>{item.targetLabel&&<span className="planner-entry-target">{item.targetLabel}</span>}<span><i/>{PUBLICATION_LABELS[item.status]}</span></button>;}
 function returnToStudio(){runGuard(()=>{if(studioSource)onOpenSource(studioSource.projectId);else onBack();});}

 return <div className="post-planner planner-product">
  <header className="planner-heading"><div><SocialWorkflowNav current="planner" disabled={locked} onStudio={returnToStudio} onChannels={()=>runGuard(()=>setSetupOpen(true))}/><h1>{setupOpen?t("Kanäle"):t("Post-Planer")}</h1><p>{setupOpen?t("Konten verbinden und bestehende Zugänge verwalten."):t("Ihre Inhalte. Ihr Kalender. Alles an einem Ort.")}</p></div><div className="planner-heading-actions">{setupOpen?<Button disabled={locked} onClick={()=>runGuard(()=>{nativeReset.current?.();setSetupOpen(false);})}><ChevronLeft size={16}/>{t("Zum Kalender")}</Button>:<Button variant="primary" className="planner-new-button" disabled={locked} onClick={()=>openComposer()}><Plus size={17}/>{t("Beitrag planen")}</Button>}<IconButton label={t("Übersicht aktualisieren")} disabled={locked} onClick={()=>void reload()}><RefreshCw size={18}/></IconButton><IconButton label={t("Hilfe zum Post-Planer")} onClick={()=>setHelpOpen(true)}><CircleHelp size={19}/></IconButton></div></header>
  {error&&!draft&&connectionEdit===undefined&&!composerOpen&&<Notice tone="error">{error}</Notice>}{notice&&!draft&&<Notice tone="success">{notice}</Notice>}
  <ConnectorSetup active={setupOpen} brands={[{key:'default',label:workspace.sources[0]?.brandLabel||'Meine Website'}]} defaultBrand="default" disabled={Boolean(busy)} onDirtyChange={setNativeDirty} onBusyChange={updateNativeBusy} onResetReady={registerNativeReset} onChanged={refreshConnections} onGuard={runGuard} onClose={()=>setSetupOpen(false)}/>
  {setupOpen&&<details className="planner-legacy-setup"><summary>{t("Instagram · erweitertes Token-Setup")}</summary><div className="planner-connections"><div><h3>{t("Instagram-Zugänge")}</h3><Button onClick={()=>openConnection(null)} disabled={locked}><Plus size={15}/>{t("Zugang hinzufügen")}</Button></div>{workspace.connections.filter(value=>(value.platform??'instagram')==='instagram'&&value.connectionMode!=='native').map(value=><article key={value.id}><div><Instagram size={20}/><span><strong>{value.label}</strong><small>{value.username?'@'+value.username:t("Kontoverbindung noch prüfen")}</small></span><b className={`planner-connection-status status-${value.status}`}>{({connected:'Verbunden',configured:'Zugang gespeichert',expired:'Abgelaufen',disconnected:'Getrennt',unconfigured:'Nicht eingerichtet'} as const)[value.status]}</b></div>{value.expiresAt&&<p>{t("Gültig bis") + " "}{new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value.expiresAt))}</p>}{value.lastError&&<p role="status">{value.lastError}</p>}<footer><button type="button" disabled={locked||value.status==='disconnected'} onClick={()=>void connectionAction('check',value)}><RefreshCw size={14}/>{t("Konto prüfen")}</button><button type="button" disabled={locked} onClick={()=>openConnection(value)}>{t("Zugang ersetzen")}</button><button type="button" disabled={locked||value.status==='disconnected'} onClick={()=>void connectionAction('disconnect',value)}><Unplug size={14}/>{t("Trennen")}</button></footer></article>)}<details><summary>{t("Technische Voraussetzungen für den Versand")}</summary>{workspace.readiness.messages.map(value=><p key={value}>{value}</p>)}<p>{t("JPEG-Bilder und H.264-MP4 bis 4 MB. Freigaben gelten für genau einen Inhalt, eine Datei, ein Konto und einen Zeitpunkt. Die Warteschlange arbeitet auch bei geschlossenem Browser.")}</p></details></div></details>}

  {!setupOpen&&<PlannerBoard entries={workspace.entries} connections={workspace.connections} brand={brand} brands={brands.map(([key,label])=>({key,label}))} onBrandChange={setBrand} onPlatformChange={setChannel} onOpen={openExisting} onCreate={day=>openComposer(day?new Date(day+'T12:00:00'):undefined)} onExport={exportPlans} onChannels={()=>runGuard(()=>setSetupOpen(true))} disabled={locked}/> }
  {composerOpen&&<Modal title={t("Was möchten Sie planen?")} description={t("Jeder Kanal bekommt eine eigene Planung. Text und Termin bleiben unabhängig bearbeitbar.")} onClose={closeComposer} footer={<><Button disabled={locked} onClick={closeComposer}>{t("Abbrechen")}</Button><Button variant="primary" busy={busy==='new-reference'} disabled={locked||sourceMode==='studio'&&!composerSource||sourceMode!=='studio'&&!composerTitle.trim()||sourceMode!=='studio'&&sourceMode!=='note'&&!composerUrl.trim()} onClick={()=>void createComposed()}><ArrowRight size={16}/>{t("Weiter zur Planung")}</Button></>}>
   {error&&<Notice tone="error">{error}</Notice>}<div className="planner-source-shortcuts"><button type="button" aria-pressed={sourceMode==='studio'} disabled={!workspace.sources.length||locked} onClick={()=>setSourceMode('studio')}><Palette size={21}/><strong>{t("Aus dem Studio")}</strong><span>{t("Gespeichertes Design")}</span></button><button type="button" disabled={locked} onClick={composerUpload}><Upload size={21}/><strong>{t("Datei hochladen")}</strong><span>{t("Fertiges Bild oder MP4")}</span></button><button type="button" aria-pressed={sourceMode==='note'} disabled={locked} onClick={()=>setSourceMode('note')}><FileText size={21}/><strong>{t("Text oder Idee")}</strong><span>{t("Zunächst vormerken")}</span></button></div><Field label={t("Kanal")}><Select value={composerChannel} disabled={locked} onChange={event=>setComposerChannel(event.target.value as PublicationPlatform)}>{PLATFORM_IDS.map(id=><option key={id} value={id}>{platformGuide(id).label}</option>)}</Select></Field><Field label={t("Inhalt")}><Select value={sourceMode} disabled={locked} onChange={event=>setSourceMode(event.target.value as typeof sourceMode)}>{workspace.sources.length>0&&<option value="studio">{t("Design aus dem Studio")}</option>}<option value="note">{t("Text oder Idee")}</option><option value="post">{t("Bild oder fertiger Beitrag als Link")}</option><option value="reel">{t("Originalvideo als Link")}</option></Select></Field>{sourceMode==='studio'?<Field label={t("Studio-Design")}><Select value={composerSource} disabled={locked} onChange={event=>setComposerSource(event.target.value)}>{workspace.sources.map(source=><option key={source.projectId} value={source.projectId}>{source.title} · {source.kind==='reel'?'Reel':'Post'}</option>)}</Select></Field>:<><Field label={t("Titel der Planung")}><Input value={composerTitle} maxLength={140} disabled={locked} onChange={event=>setComposerTitle(event.target.value)} placeholder={sourceMode==='note'?t("Zum Beispiel: Einblick ins nächste Projekt"):t("Zum Beispiel: Neues Video zur Produktidee")}/></Field>{sourceMode!=='note'&&<Field label={t("HTTPS-Link zur Originaldatei oder eigenen Ablage")} hint={t("Wir merken uns nur den Link. Die Datei wird weder abgerufen noch zu einer Plattform hochgeladen.")}><Input type="url" value={composerUrl} maxLength={2000} disabled={locked} onChange={event=>setComposerUrl(event.target.value)} placeholder="https://…"/></Field>}<Field label={t("Text oder erste Notizen")}><Textarea rows={4} value={composerCaption} maxLength={2200} disabled={locked} onChange={event=>setComposerCaption(event.target.value)}/></Field></>}<p className="planner-hint">{t("Fertige JPG-, PNG- oder MP4-Dateien bis 4 MB können Sie über „Beitrag hochladen“ privat ablegen. Größere Videos bleiben als Medien-Link in Ihrer eigenen Ablage.")}</p>
  </Modal>}
  {helpOpen&&<Modal title={t("Vom Entwurf zum Beitrag.")} onClose={()=>setHelpOpen(false)}><div className="planner-quick-help"><ol><li><strong>{t("Inhalt wählen")}</strong><p>{t("Ein Design aus dem Studio, eine fertige Datei oder eine neue Textidee.")}</p></li><li><strong>{t("Text & Termin ergänzen")}</strong><p>{t("Kanal wählen, Caption prüfen und Datum festlegen. Sie können die Planung zunächst als Entwurf speichern.")}</p></li><li><strong>{t("Bewusst freigeben")}</strong><p>{t("Für automatisches Senden ein verbundenes Konto auswählen, die Medien vorbereiten und die Veröffentlichung freigeben. TikTok wird zur abschließenden Veröffentlichung an Ihre TikTok-Inbox übergeben.")}</p></li></ol><details><summary>{t("Was bedeuten die Statuswerte?")}</summary><p>{t("Entwurf: noch in Arbeit. Freigegeben: Versand vorgemerkt. Geplant: von der Warteschlange übernommen. Veröffentlicht: vom Anbieter bestätigt. Manuelle Abschlüsse sind separat gekennzeichnet.")}</p><p>{t("Ein unklarer, bereits begonnener Versand wird zur Prüfung angehalten und nicht blind wiederholt.")}</p></details><Button onClick={()=>{setHelpOpen(false);runGuard(()=>setSetupOpen(true));}}><Link2 size={16}/>{t("Kanäle verwalten")}</Button></div></Modal>}
  {draft&&<Modal title={entry?t("Planung bearbeiten"):t("Neue Planung")} description={`${entry?PUBLICATION_LABELS[entry.status]+' · Version '+entry.revision:'Noch nicht gespeichert'} · ${selectedGuide.label}`} wide onClose={closeEditor} footer={<div className="planner-editor-footer"><span>{dirty?t("Ungespeicherte Änderungen"):entry?t("Planung gespeichert"):t("Noch nicht gespeichert")}</span><Button onClick={closeEditor} disabled={locked}>{t("Schließen")}</Button>{writable&&<Button variant="primary" busy={busy==='save'} disabled={!dirty||locked||timeInvalid} onClick={()=>void save()}><Save size={16}/>{t("Planung speichern")}</Button>}</div>}>
   {error&&<Notice tone="error">{error}</Notice>}{notice&&<Notice tone="success">{notice}</Notice>}{conflict&&<Button onClick={()=>openExisting(draft.id)} disabled={locked}><RefreshCw size={15}/>{t("Aktuellen Stand laden")}</Button>}
   <div className="planner-editor-layout"><div className="planner-editor-preview">{entry?.media&&(!draft.carousel||entry.mediaItems?.some(item=>item.slideIndex===previewIndex))?<div className="planner-current-media">{entry.media.kind==='image'?<img src={'/api/admin/social/planner/media/'+(draft.carousel?(entry.mediaItems?.find(item=>item.slideIndex===previewIndex)??entry.media).id:entry.media.id)} alt={(draft.carousel?draft.carouselAltTexts?.[previewIndex]:'')||draft.altText||t("Vorbereiteter Beitrag")}/>:<video src={'/api/admin/social/planner/media/'+entry.media.id} controls playsInline preload="metadata"/>}</div>:reference?<div className="planner-reference-preview"><FileText size={28}/><strong>{reference.title}</strong><span>{reference.kind==='note'?t("Text und Idee"):t("Originaldatei in eigener Ablage")}</span>{reference.url&&<a href={reference.url} target="_blank" rel="noopener noreferrer">{t("Original öffnen") + " "}<ExternalLink size={15}/></a>}<p>{draft.caption||t("Hier ist Platz für Ihren Beitrag.")}</p></div>:uploaded&&entry?.media?<div className="planner-upload-saved-preview">{entry.media.kind==='image'?<img src={'/api/admin/social/planner/media/'+entry.media.id} alt={draft.altText||t("Fertiger Beitrag")}/>:<video src={'/api/admin/social/planner/media/'+entry.media.id} controls preload="metadata"/>}<strong>{t("Fertiger Beitrag")}</strong><span>{isUploadedSource(draft.source)&&draft.source.filename}</span><small>{entry.media.width} × {entry.media.height} px · {(entry.media.bytes/1024/1024).toFixed(1)} MB</small></div>:project?<CanvasPreview project={{...project,slides:[project.slides[draft.carousel?previewIndex:draft.slideIndex]||project.slides[0]]}} label={t("Eingefrorener Quellentwurf")}/>:<div className="planner-preview-loading" role="status"><LoaderCircle size={22}/>{t("Quellentwurf laden …")}</div>}
    {draft.carousel&&<><nav className="pp-carousel-slides" aria-label={t("Carousel-Folien prüfen")}>{Array.from({length:draft.source.slides},(_,index)=><button key={index} type="button" aria-label={'Folie '+(index+1)+' anzeigen'} aria-pressed={previewIndex===index} onClick={()=>setPreviewIndex(index)}>{index+1}</button>)}</nav><p>{entry?.mediaItems?.length??0}{" " + t("von") + " "}{draft.source.slides}{" " + t("Folien vorbereitet · ein gemeinsamer Beitrag.")}</p></>}<p>{reference?t("Text und Verweis bleiben in dieser Planung. Es wird kein Inhalt von der verlinkten Website geladen."):uploaded?t("Die geprüfte Datei bleibt unverändert gespeichert. Caption und Termin bearbeiten Sie daneben."):<>{t("Quelle:") + " "}{draft.source.title}{studioSource?' · Version '+(studioSource.projectRevision||'Vorlage'):''}{t(". Änderungen im Studio verändern diesen gespeicherten Planungsstand nicht.")}</>}</p>{studioSource&&<Button variant="quiet" onClick={()=>runGuard(()=>onOpenSource(studioSource.projectId))} disabled={locked}><ExternalLink size={15}/>{t("Im Studio bearbeiten")}</Button>}
    {entry?.media&&(!draft.carousel||entry.mediaItems?.some(item=>item.slideIndex===previewIndex))&&<div className="planner-prepared"><h3><ShieldCheck size={16}/>{t("Geprüfte Datei")}</h3><span>{entry.media.mimeType==='image/jpeg'?'JPEG':'MP4'} · {entry.media.width} × {entry.media.height} px · {(entry.media.bytes/1024/1024).toFixed(1)} MB</span><Button onClick={()=>void downloadMedia()} disabled={locked}><Download size={15}/>{t("Datei herunterladen")}</Button></div>}
   </div>
   <div className="planner-editor-fields"><Field label={draft.kind==='text'?t("Beitragstext"):'Caption'} hint={t("{0} / 2.200 Zeichen im Planer. Die Grenzen des Zielkanals vor dem Veröffentlichen prüfen.", { 0: draft.caption.length })}><Textarea rows={5} maxLength={2200} disabled={!writable||locked} value={draft.caption} onChange={event=>patch({caption:event.target.value})}/></Field><div className="cms-form-grid"><Field label={t("Kanal")}><Select value={selectedPlatform} disabled={!writable||locked} onChange={event=>patch({platform:event.target.value as PublicationPlatform,delivery:'manual',accountId:null,connectionMode:undefined,providerOptions:undefined,carousel:undefined,carouselAltTexts:undefined})}>{PLATFORM_IDS.map(id=><option key={id} value={id}>{platformGuide(id).label}</option>)}</Select></Field><Field label={t("Veröffentlichung")}><Select value={effectiveDelivery(draft)} disabled={!writable||locked} onChange={event=>patch({delivery:event.target.value as 'manual'|'automatic'|'handoff',accountId:null,connectionMode:draft.carousel&&event.target.value==='automatic'?'native':undefined})}><option value="manual">{t("Selbst veröffentlichen")}</option>{executable&&<option value={selectedSpec?.delivery??'automatic'}>{selectedSpec?.delivery==='handoff'?t("TikTok · zur Inbox übergeben"):selectedGuide.label+' · nach Freigabe senden'}</option>}</Select></Field></div>
    <details className="planner-channel-help"><summary>{t("Hinweise zum Versand auf") + " "}{selectedGuide.label}</summary><p>{manual?selectedGuide.manualHint:handoff?t("Nach Ihrer Freigabe wird das Video zum Termin an die TikTok-Inbox übergeben. Sie veröffentlichen abschließend in TikTok."):t("Erst eine ausdrückliche Freigabe mit geprüftem Konto, Inhalt und Termin startet den Versand.")}</p><details><summary>{t("Was ist bei") + " "}{selectedGuide.label}{" " + t("möglich?")}</summary><p>{selectedSpec?.hint??selectedGuide.apiSummary}</p><p>{selectedSpec?t("Unter „Kanäle verbinden“ eigene App, Konto und Ziel einrichten."):selectedGuide.connectionHint}</p>{selectedGuide.documentation.map(link=><a key={link.url} href={link.url} target="_blank" rel="noopener noreferrer">{link.label} <ExternalLink size={13}/></a>)}</details></details>
    {manual?<Field label={t("Zielkonto oder Kanalbezeichnung")} hint={t("Zum Beispiel @IhrName, Ihre Unternehmensseite oder eine Pinterest-Pinnwand. Das ist eine Notiz, keine Kontoverbindung.")}><Input value={draft.targetLabel??''} maxLength={100} disabled={!writable||locked} onChange={event=>patch({targetLabel:event.target.value})}/></Field>:<><Field label={selectedGuide.label+' · verbundenes Ziel'}><Select value={draft.accountId||''} disabled={!writable||locked} onChange={event=>patch({accountId:event.target.value||null,connectionMode:connections.find(value=>value.id===event.target.value)?.connectionMode})}><option value="">{t("Später auswählen")}</option>{connections.map(value=><option key={value.id} value={value.id} disabled={value.status!=='connected'||Boolean(draft.carousel&&value.connectionMode!=='native')}>{value.label} · {value.status==='connected'?t("verbunden"):t("noch nicht sendebereit")}</option>)}</Select></Field>{!connections.length&&<p className="planner-hint">{t("Noch kein passendes Ziel verbunden. Unter „Kanäle verbinden“ einrichten; die Planung können Sie bereits speichern.")}</p>}</>}
    {studioSource&&<details className="planner-optional-fields"><summary>{t("Design & Format")}</summary><Field label={t("Studio-Design")}><Select value={studioSource.projectId} disabled={!writable||locked} onChange={event=>void changeSource(event.target.value)}>{!workspace.sources.some(value=>value.projectId===studioSource.projectId)&&<option value={studioSource.projectId}>{draft.source.title}{" " + t("· eingefrorener Stand")}</option>}{workspace.sources.map(value=><option key={value.projectId} value={value.projectId}>{value.title} · {value.kind==='reel'?'Reel':'Post'}</option>)}</Select></Field>{writable&&workspace.sources.some(value=>value.projectId===studioSource.projectId&&value.snapshotHash!==draft.source.snapshotHash)&&<Button disabled={locked} onClick={()=>void changeSource(studioSource.projectId)}><RefreshCw size={15}/>{t("Aktuellen Quellstand übernehmen")}</Button>}<div className="cms-form-grid"><Field label="Format"><Select value={draft.kind} disabled={!writable||locked} onChange={event=>patch({kind:event.target.value as 'image'|'reel',slideIndex:0,carousel:undefined,carouselAltTexts:undefined})}><option value="image">{t("Einzelbild")}</option>{studioSource.kind==='reel'&&<option value="reel">{t("Reel · gesamte Timeline")}</option>}</Select></Field>{draft.kind==='image'&&selectedPlatform==='instagram'&&draft.source.slides>=2&&draft.source.slides<=MAX_CAROUSEL_ITEMS&&<Field label={t("Beitragsformat")}><Select value={draft.carousel?'carousel':'single'} disabled={!writable||locked} onChange={event=>changeCarousel(event.target.value==='carousel')}><option value="single">{t("Einzelbild")}</option><option value="carousel">{t("Carousel · alle") + " "}{draft.source.slides}{" " + t("Folien")}</option></Select></Field>}{draft.kind==='image'&&!draft.carousel&&<Field label={t("Folie")}><Select value={draft.slideIndex} disabled={!writable||locked} onChange={event=>patch({slideIndex:Number(event.target.value)})}>{Array.from({length:draft.source.slides},(_,index)=><option key={index} value={index}>Slide {index+1}</option>)}</Select></Field>}</div></details>}
    {uploaded&&<section className="planner-upload-source"><h3>{t("Fertiger") + " "}{draft.kind==='reel'?t("MP4-Beitrag"):t("Bildbeitrag")}</h3><p>{t("Die Datei ist privat gespeichert und geprüft. Der Planer nimmt JPEG und H.264-MP4 bis 4 MB an. Die Eignung für den gewählten Anbieter wird vor der Freigabe zusätzlich geprüft.")}</p><Button disabled={!writable||dirty||locked} onClick={()=>openUpload(true)}><Upload size={15}/>{t("Datei ersetzen")}</Button>{dirty&&<p>{t("Vor dem Ersetzen bitte Änderungen speichern.")}</p>}</section>}
    {draft.kind==='image'&&draft.carousel&&draft.carouselAltTexts?<details className="pp-carousel-alt"><summary>{t("Bildbeschreibungen für") + " "}{draft.source.slides}{" " + t("Folien")}</summary><p>{t("Beschreiben Sie die Aussage jeder Folie. Das hilft Menschen, die einen Screenreader nutzen.")}</p>{draft.carouselAltTexts.map((text,index)=><Field key={index} label={'Folie '+(index+1)}><Textarea rows={2} maxLength={1000} value={text} disabled={!writable||locked} onChange={event=>patch({carouselAltTexts:draft.carouselAltTexts!.map((value,i)=>i===index?event.target.value:value)})}/></Field>)}</details>:draft.kind==='image'&&<details className="planner-optional-fields"><summary>{t("Bildbeschreibung")}</summary><Field label={t("Bildbeschreibung")} hint={t("Beschreiben Sie den wesentlichen Bildinhalt. Die Zielplattform kann andere Textgrenzen haben.")}><Textarea rows={2} maxLength={1000} value={draft.altText} disabled={!writable||locked} onChange={event=>patch({altText:event.target.value})}/></Field></details>}
    {!manual&&selectedSpec&&<section className="planner-provider-options"><h3>{selectedGuide.label}{" " + t("· Beitragsangaben")}</h3>{['youtube','pinterest'].includes(selectedPlatform)&&<Field label={selectedPlatform==='youtube'?t("Videotitel · erforderlich"):t("Pin-Titel")}><Input value={draft.providerOptions?.title??''} maxLength={100} disabled={!writable||locked} onChange={event=>patchOptions({title:event.target.value||undefined})}/></Field>}{selectedPlatform==='youtube'&&<><Field label={t("Ist dieses Video speziell für Kinder bestimmt?")} hint={t("Wählen Sie ausdrücklich eine Antwort. Diese Angabe wird an YouTube übergeben.")}><Select value={draft.providerOptions?.madeForKids===undefined?'':String(draft.providerOptions.madeForKids)} disabled={!writable||locked} onChange={event=>patchOptions({madeForKids:event.target.value===''?undefined:event.target.value==='true'})}><option value="">{t("Bitte ausdrücklich auswählen …")}</option><option value="false">{t("Nein, nicht speziell für Kinder")}</option><option value="true">{t("Ja, speziell für Kinder")}</option></Select></Field><Field label={t("YouTube-Kategorie-ID · optional")}><Input value={draft.providerOptions?.categoryId??''} inputMode="numeric" pattern="[0-9]{1,3}" maxLength={3} disabled={!writable||locked} onChange={event=>patchOptions({categoryId:event.target.value||undefined})}/></Field><p>{t("Der Upload wird privat vorbereitet. Die Freigabe gilt für den gewählten Veröffentlichungszeitpunkt und diese Zielgruppenangabe.")}</p></>}{connectorLinkSupported(selectedPlatform,draft.kind)&&<Field label={t("Ziel-Link · optional")} hint={t("Eine HTTPS-Adresse zum Beitrag. Dieser Link wird nicht als Mediendatei geladen.")}><Input type="url" value={draft.providerOptions?.link??''} maxLength={2048} disabled={!writable||locked} onChange={event=>patchOptions({link:event.target.value||undefined})}/></Field>}{handoff&&<p>{t("Caption, Musik, Sichtbarkeit und Veröffentlichung prüfen und bestätigen Sie später in TikTok. Die Übergabe ist noch keine öffentliche Veröffentlichung.")}</p>}</section>}
    <div className="cms-form-grid"><Field label={t("Datum und Uhrzeit")}><Input type="datetime-local" value={wall} disabled={!writable||locked} onChange={event=>changeTime(event.target.value)}/></Field><Field label={t("Zeitzone")}><Select value={draft.timeZone} disabled={!writable||locked} onChange={event=>changeTime(wall,event.target.value)}>{[...new Set([draft.timeZone,...zones])].map(value=><option key={value}>{value}</option>)}</Select></Field></div>{wall&&choices.length===0&&<Notice tone="error">{t("Diese Ortszeit ist ungültig oder liegt in einer Zeitumstellung. Bitte eine andere Uhrzeit wählen.")}</Notice>}{choices.length>1&&<Field label={t("Diese Uhrzeit kommt zweimal vor. Welcher Zeitpunkt ist gemeint?")}><Select value={draft.scheduledAt||''} onChange={event=>patch({scheduledAt:event.target.value||null})} disabled={!writable||locked}><option value="">{t("UTC-Abstand ausdrücklich wählen")}</option>{choices.map(value=><option key={value.instant} value={value.instant}>{value.label}</option>)}</Select></Field>}{draft.scheduledAt&&<p className="planner-hint"><Clock3 size={14}/>{formatPlannedTime(draft.scheduledAt,draft.timeZone)}</p>}
    {studioSource&&!manual&&<section className="planner-media-actions"><h3>{t("Die tatsächliche Datei vorbereiten.")}</h3><p>{draft.kind==='image'?t("Das Studio rendert die gewählte Slide als JPEG. Transparente Flächen erhalten einen weißen Hintergrund. Es wird nicht automatisch beschnitten."):t("Das Studio rendert die gesamte Timeline als H.264-MP4, wenn Ihr Browser das unterstützt. WebM wird nicht an den Anbieter gesendet.")}{" " + t("Maximal 4 MB.")}</p><div><Button onClick={()=>void prepare()} disabled={!entry||dirty||!writable||locked||!project}><ImageIcon size={15}/>{entry?.media?t("Medien neu vorbereiten"):t("Aus Studio vorbereiten")}</Button><label className={`cms-button${!entry||dirty||!writable||locked?' planner-upload-disabled':''}`}>{t("Eigene Datei wählen")}<input type="file" accept={draft.kind==='image'?'image/jpeg,image/png,image/webp':'video/mp4'} disabled={!entry||dirty||!writable||locked} onChange={event=>{void uploadFile(event.target.files?.[0]);event.target.value='';}}/></label></div>{(!entry||dirty)&&<p className="planner-hint">{t("Bitte zuerst die Planung speichern.")}</p>}{busy==='prepare'&&<p className="planner-progress" role="status"><LoaderCircle size={16} className="cms-spin"/>{progress}{abort.current&&<button type="button" onClick={()=>abort.current?.abort()}>{t("Abbrechen")}</button>}</p>}</section>}
    <details className="planner-handoff"><summary>{t("Weitere Aktionen & Export")}</summary>{busy==='design-download'&&<p className="planner-progress" role="status"><LoaderCircle size={16} className="cms-spin"/>{progress||t("Design exportieren ?")}<button type="button" onClick={()=>abort.current?.abort()}>{t("Abbrechen")}</button></p>}<div><Button onClick={()=>void copyCaption()} disabled={locked}><Copy size={15}/>{t("Text kopieren")}</Button>{studioSource&&entry&&<Button disabled={dirty||locked} busy={busy==='design-download'} onClick={()=>void downloadDesign()}><Download size={15}/>{t("Design herunterladen")}</Button>}{entry&&<Button disabled={dirty||locked} onClick={()=>exportPlans('text',[entry])}><Download size={15}/>{t("Planung exportieren")}</Button>}{entry&&!uploaded&&<Button disabled={dirty||locked} onClick={()=>{setCopyChannel(selectedPlatform);setCopyTarget('');setCopyOpen(!copyOpen);}} aria-expanded={copyOpen}><Copy size={15}/>{t("Für weiteren Kanal kopieren")}</Button>}</div>{uploaded&&<p>{t("Eine eigene Planung für einen anderen Kanal legen Sie mit einem erneuten Upload an. So bleibt jede Datei ihrem geprüften Stand zugeordnet.")}</p>}{copyOpen&&<div className="planner-copy-fields"><Field label={t("Kanal der Kopie")}><Select value={copyChannel} onChange={event=>setCopyChannel(event.target.value as PublicationPlatform)} disabled={locked}>{PLATFORM_IDS.map(id=><option key={id} value={id}>{platformGuide(id).label}</option>)}</Select></Field><Field label={t("Zielkonto der Kopie")}><Input value={copyTarget} maxLength={100} disabled={locked} onChange={event=>setCopyTarget(event.target.value)}/></Field><Button disabled={dirty||locked} busy={busy==='copy'} onClick={()=>void copyPlan()}>{t("Eigene Kopie anlegen")}</Button><p>{t("Die Kopie bekommt keinen Termin und keine Versandfreigabe. Das Original bleibt unverändert.")}</p></div>}</details>
    {entry&&(manual?<section className="planner-send-actions"><h3>{entry.status==='manual_completed'?t("Von Ihnen als veröffentlicht markiert."):t("Veröffentlichen Sie den Beitrag selbst.")}</h3>{entry.status==='manual_completed'?<><p>{entry.manualCompletion?.at&&new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(entry.manualCompletion.at))}{" " + t("· Manueller Abschluss, keine API-Bestätigung.")}</p><Button disabled={dirty||locked} onClick={()=>void act('reopen')}><RefreshCw size={15}/>{t("Wieder als offen markieren")}</Button></>:<><p>{t("Text und Medien in") + " "}{selectedGuide.label}{" " + t("prüfen und dort veröffentlichen. Erst danach den Beitrag hier abschließen. Der Termin löst keinen Versand aus.")}</p><Button disabled={dirty||locked} onClick={()=>void act('complete')}><Check size={16}/>{t("Als von mir veröffentlicht markieren")}</Button>{dirty&&<p>{t("Bitte zuerst die Änderungen speichern.")}</p>}</>}</section>:entry.status==='awaiting_platform'?<section className="planner-send-actions planner-handoff-receipt"><h3>{t("An die TikTok-Inbox übergeben.")}</h3><p>{t("Die Upload-Übergabe wurde bestätigt. Öffnen Sie TikTok, prüfen Sie Caption, Musik und Sichtbarkeit und schließen Sie die Veröffentlichung dort ab. Dies ist keine Bestätigung einer öffentlichen Veröffentlichung.")}</p>{entry.manualCompletion?<p>{t("Von Ihnen am") + " "}{new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(entry.manualCompletion.at))}{" " + t("als in TikTok veröffentlicht bestätigt. Keine öffentliche API-Bestätigung.")}</p>:<Button disabled={locked||dirty} onClick={()=>void act('complete')}><Check size={16}/>{t("In TikTok selbst veröffentlicht bestätigen")}</Button>}</section>:<section className="planner-send-actions"><h3>{entry.status==='published'?'Von '+selectedGuide.label+' bestätigt.':handoff?t("Sie geben die TikTok-Übergabe frei."):t("Sie geben den Versand frei.")}</h3>{entry.process.lastError&&<Notice tone={entry.status==='failed'?'error':'info'}>{entry.process.lastError}</Notice>}{entry.status==='published'?<p>{t("Bestätigt am") + " "}{entry.process.confirmedAt&&new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(entry.process.confirmedAt))}{t(". Dieser Veröffentlichungsversuch bleibt unverändert erhalten.")}</p>:<><p>{handoff?t("Die Freigabe startet zum Termin die Übergabe in Ihre TikTok-Inbox. Die öffentliche Veröffentlichung schließen Sie selbst in TikTok ab."):t("Ein Termin allein sendet nichts. Ein geprüftes Zielkonto, geeigneter Inhalt und die eingerichtete Warteschlange sind nötig. Änderungen heben eine bisherige Freigabe auf.")}</p><div>{entry.status==='needs_review'&&!entry.process.publishStartedAt&&<Button disabled={dirty||locked||!writable} onClick={()=>void save()}><RefreshCw size={15}/>{t("Als Entwurf neu prüfen")}</Button>}<Button variant="primary" disabled={!canApprove} onClick={()=>{setApproveOpen(true);setApprovalChecked(false);}}><ShieldCheck size={16}/>{t("Freigabe prüfen")}</Button>{entry.status==='scheduling'&&entry.approval&&<Button disabled={dirty||locked} onClick={()=>void act('reconcile')}><RefreshCw size={15}/>{t("Queue erneut vormerken")}</Button>}{entry.status==='needs_review'&&entry.process.publishStartedAt&&<Button disabled={dirty||locked} onClick={()=>void act('reconcile')}><RefreshCw size={15}/>{selectedGuide.label}{t("-Status prüfen")}</Button>}{!['draft','cancelled','published','manual_planned','manual_completed'].includes(entry.status)&&<Button disabled={dirty||locked||Boolean(entry.process.publishStartedAt)} onClick={()=>void act('cancel')}>{t("Planung stoppen")}</Button>}</div>{!canApprove&&<p className="planner-hint">{dirty?t("Zuerst die Änderungen speichern."):!executable?t("Dieses Format wird für den gewählten Kanal manuell geplant. Verlinkte Medien werden nicht geladen."):!optionsReady?t("Bitte Videotitel und die ausdrückliche YouTube-Zielgruppenangabe ergänzen."):!workspace.readiness.enabled||!workspace.readiness.queue||!workspace.readiness.media||!workspace.readiness.publicOrigin||workspace.readiness.credentials===false?t("Der Versand ist noch nicht vollständig eingerichtet."):draft.carousel&&!carouselItemsReady(entry)?t("Bitte alle Carousel-Folien vorbereiten und die Reihenfolge prüfen."):draft.kind!=='text'&&!entry.media?t("Bitte die tatsächlichen Medien vorbereiten."):selectedConnection?.status!=='connected'?t("Bitte ein verbundenes Zielkonto für diesen Kanal auswählen."):!entry.scheduledAt?t("Bitte Datum, Uhrzeit und Zeitzone festlegen."):entry.process.publishStartedAt?t("Dieser bereits begonnene Versuch muss zuerst geprüft werden. Er wird nicht wiederholt."):t("Diese Planung ist bereits freigegeben oder muss bewusst neu vorbereitet werden.")}</p>}</>}</section>)}
   </div></div>
  </Modal>}
  {uploadTarget&&<FinishedPostUpload target={uploadTarget} onDirtyChange={setUploadDirty} onClose={()=>{setUploadTarget(null);setUploadDirty(false);}} onStored={next=>{store(next);setProject(null);setUploadTarget(null);setUploadDirty(false);setError('');setNotice('Datei geprüft und privat gespeichert. Ergänzen Sie Kanal, Caption und Termin. Es wurde nichts gesendet.');}}/>}
  {pendingLeave&&<Modal title={t("Änderungen behalten?")} description={pendingLeave.secondary?t("Es sind noch Eingaben oder eine Dateiauswahl offen."):t("Ihre Planung enthält ungespeicherte Änderungen.")} onClose={()=>{if(!locked)setPendingLeave(null);}} footer={<><Button disabled={locked} onClick={()=>{const action=pendingLeave.action;setPendingLeave(null);discardSecondary();action();}}>{t("Verwerfen & wechseln")}</Button>{!pendingLeave.secondary&&<Button variant="primary" busy={busy==='save'} disabled={locked||timeInvalid} onClick={()=>void(async()=>{if(await save()&&JSON.stringify(draftRef.current)===savedRef.current){const action=pendingLeave.action;setPendingLeave(null);discardSecondary();action();}})()}>{t("Speichern & wechseln")}</Button>}<Button variant="quiet" disabled={locked} onClick={()=>setPendingLeave(null)}>{t("Hier bleiben")}</Button></>}><p>{pendingLeave.secondary?t("Zugänge, Uploads und noch nicht übernommene Ideen werden nicht stillschweigend gespeichert. Bleiben Sie hier, um diese Eingaben abzuschließen."):t("Bei einem Speicherfehler bleiben Ihre Eingaben erhalten.")}</p>{error&&<Notice tone="error">{error}</Notice>}</Modal>}
  {approveOpen&&entry&&draft&&<Modal title={handoff?t("Video an die TikTok-Inbox übergeben?"):'Diesen Beitrag an '+selectedGuide.label+' senden?'} description={t("Die Freigabe gilt nur für diesen Inhalt, das gewählte Ziel und diesen Zeitpunkt.")} onClose={()=>{if(!locked)setApproveOpen(false);}} footer={<><Button onClick={()=>setApproveOpen(false)} disabled={locked}>{t("Zurück")}</Button><Button variant="primary" disabled={!approvalChecked||!canApprove} busy={busy==='approve'} onClick={()=>void act('approve')}><ShieldCheck size={16}/>{handoff?t("Inbox-Übergabe freigeben"):t("Verbindlich freigeben")}</Button></>}><div className="planner-approval-summary"><dl><div><dt>{t("Beitrag")}</dt><dd>{draft.providerOptions?.title||draft.source.title}</dd></div><div><dt>{t("Zielkonto")}</dt><dd>{selectedConnection?.label}{selectedConnection?.username?' · @'+selectedConnection.username:''}</dd></div><div><dt>{t("Zeitpunkt")}</dt><dd>{formatPlannedTime(draft.scheduledAt,draft.timeZone)}</dd></div><div><dt>{t("Inhalt")}</dt><dd>{draft.carousel?'Carousel · alle '+draft.source.slides+' geprüften Folien in der angezeigten Reihenfolge':draft.kind==='text'?t("Textbeitrag"):entry.media?.mimeType==='image/jpeg'?t("Geprüftes JPEG-Einzelbild"):t("Geprüftes MP4-Video")}</dd></div>{['facebook','youtube'].includes(selectedPlatform)&&<div><dt>{t("Sichtbarkeit")}</dt><dd>{selectedPlatform==='facebook' ? t("Öffentlich auf der gewählten Facebook-Seite") : t("Öffentlich")}</dd></div>}{selectedPlatform==='youtube'&&<div><dt>{t("Speziell für Kinder")}</dt><dd>{draft.providerOptions?.madeForKids?t("Ja"):t("Nein")}</dd></div>}{draft.providerOptions?.link&&<div><dt>{t("Ziel-Link")}</dt><dd>{draft.providerOptions.link}</dd></div>}</dl><p>{draft.caption||t("Ohne Caption")}</p>{handoff&&<Notice>{t("Die Übergabe endet in der TikTok-Inbox. Sie prüfen und veröffentlichen den Beitrag anschließend selbst in TikTok.")}</Notice>}<Toggle checked={approvalChecked} onChange={setApprovalChecked} label={handoff?t("Inhalt, TikTok-Konto und Zeitpunkt stimmen. Ich gebe die Inbox-Übergabe frei."):t("Inhalt, Zielkonto und Zeitpunkt stimmen. Ich gebe diese Veröffentlichung frei.")} hint={t("Ein bereits an den Anbieter übergebener Vorgang kann hier nicht zurückgeholt werden.")}/></div></Modal>}
  {connectionEdit!==undefined&&<Modal title={t("Eigener Instagram-Zugang")} description={t("Erweiterte Einrichtung für den Betreiber. Der Zugang bleibt verschlüsselt auf dem Server.")} onClose={closeConnection} footer={<><Button onClick={closeConnection} disabled={locked}>{t("Abbrechen")}</Button><Button variant="primary" disabled={!connectionForm.confirmed||locked} busy={busy==='connection-save'} onClick={()=>void saveConnection()}>{t("Verschlüsselt speichern")}</Button></>}>
   {error&&<Notice tone="error">{error}</Notice>}<p className="planner-hint">{t("Verwenden Sie Ihr eigenes Business- oder Creator-Konto mit Instagram Login. Ein gespeicherter Zugang allein gibt noch keinen Beitrag frei.")}</p><Field label={t("Bezeichnung")}><Input className="planner-credential-input" value={connectionForm.label} disabled={locked} onChange={event=>setConnectionForm({...connectionForm,label:event.target.value})}/></Field><Field label={t("Instagram-Konto-ID")}><Input className="planner-credential-input" autoComplete="off" inputMode="numeric" value={connectionForm.accountId} disabled={locked} onChange={event=>setConnectionForm({...connectionForm,accountId:event.target.value})}/></Field><Field label={t("Eigener langlebiger Zugriffstoken")} hint={t("Der Token wird nach dem Speichern nicht wieder angezeigt. Zum Ersetzen einen neuen eigenen Zugang eintragen.")}><Input className="planner-credential-input" type="password" autoComplete="new-password" value={connectionForm.accessToken} disabled={locked} onChange={event=>setConnectionForm({...connectionForm,accessToken:event.target.value})}/></Field><Field label={t("Ablaufdatum und Uhrzeit · UTC")} hint={t("Die tatsächliche UTC-Ablaufzeit aus Meta übernehmen. Der Zugang muss mindestens eine Stunde über den geplanten Beitrag hinaus gültig sein.")}><Input className="planner-credential-input" type="datetime-local" value={connectionForm.expiresAt} disabled={locked} autoComplete="off" onChange={event=>setConnectionForm({...connectionForm,expiresAt:event.target.value})}/></Field><p className="planner-hint"><a href="https://developers.facebook.com/docs/instagram-platform/instagram-api-with-instagram-login/business-login/" target="_blank" rel="noopener noreferrer">{t("Offizielle Meta-Anleitung öffnen") + " "}<ExternalLink size={14}/></a>{" " + t("· Tokens vor Ablauf manuell ersetzen.")}</p><details className="cms-details"><summary>{t("Berechtigungen und Kundenkonten")}</summary><p className="planner-hint">{t("Ihre Meta-App benötigt instagram_business_basic und instagram_business_content_publish. Für fremde Kundenkonten kann eine Meta-App-Prüfung erforderlich sein.")}</p></details><Toggle checked={connectionForm.confirmed} onChange={confirmed=>setConnectionForm({...connectionForm,confirmed})} label={t("Eigene App, Professional-Konto und erforderliche Berechtigungen sind eingerichtet.")}/>
  </Modal>}
 </div>;
